def _build_project_browser_autonomous_dev_loop_input_state(
    *,
    payload_from_final_override: Mapping[str, Any] | None,
    payload_from_normalized_state: Mapping[str, Any] | None,
    payload_from_explicit_input: Mapping[str, Any] | None,
    payload_from_explicit_real_input_injection: Mapping[str, Any] | None,
    payload_from_synthetic_seed: Mapping[str, Any] | None,
) -> dict[str, Any]:
    required_input_fields = ["project_request_text"]
    status = "dev_loop_input_waiting_for_project_request"
    next_action = "provide_project_request"

    candidate_sources: list[tuple[str, dict[str, Any]]] = []
    for source_name, payload in (
        ("final_approved_restart_execution_override", payload_from_final_override),
        ("existing_normalized_runner_state", payload_from_normalized_state),
        ("explicit_dev_loop_input_fields", payload_from_explicit_input),
        (
            "prompt258_explicit_real_input_injection",
            payload_from_explicit_real_input_injection,
        ),
        ("prompt253_synthetic_dev_loop_input_seed", payload_from_synthetic_seed),
    ):
        candidate_sources.append(
            (source_name, dict(payload) if isinstance(payload, Mapping) else {})
        )

    selected_payload: dict[str, Any] = {}
    selected_source_name = ""
    for source_name, payload in candidate_sources:
        if not payload:
            continue
        has_materialized_input = bool(
            _normalize_text(payload.get("project_request_text"), default="")
            or _normalize_text(payload.get("analysis_summary"), default="")
            or _normalize_text(payload.get("codex_result_summary"), default="")
            or bool(_normalize_string_list(payload.get("constraints")))
            or (
                isinstance(payload.get("roadmap_pr_queue"), list)
                and bool(payload.get("roadmap_pr_queue"))
            )
            or isinstance(payload.get("active_pr"), Mapping)
            or ("active_pr_index" in payload)
            or ("codex_validation_passed" in payload)
        )
        if has_materialized_input:
            selected_payload = payload
            selected_source_name = source_name
            break

    project_request_text = _normalize_text(
        selected_payload.get("project_request_text"),
        default="",
    )
    constraints = _normalize_string_list(selected_payload.get("constraints"))
    analysis_summary = _normalize_text(
        selected_payload.get("analysis_summary"),
        default="",
    )
    roadmap_pr_queue: list[dict[str, Any]] = []
    roadmap_pr_queue_candidate = selected_payload.get("roadmap_pr_queue")
    if isinstance(roadmap_pr_queue_candidate, list):
        for entry in roadmap_pr_queue_candidate:
            if isinstance(entry, Mapping):
                roadmap_pr_queue.append(dict(entry))
    active_pr_index = _as_non_negative_int(
        selected_payload.get("active_pr_index"),
        default=0,
    )
    active_pr = (
        dict(selected_payload.get("active_pr"))
        if isinstance(selected_payload.get("active_pr"), Mapping)
        else {}
    )
    if not active_pr and 0 <= active_pr_index < len(roadmap_pr_queue):
        active_pr = dict(roadmap_pr_queue[active_pr_index])
    codex_result_summary = _normalize_text(
        selected_payload.get("codex_result_summary"),
        default="",
    )

    codex_validation_passed = False
    codex_validation_raw = selected_payload.get("codex_validation_passed")
    if isinstance(codex_validation_raw, bool):
        codex_validation_passed = codex_validation_raw
    else:
        codex_validation_passed = (
            _normalize_text(codex_validation_raw, default="").lower()
            in {"true", "1", "yes", "passed"}
        )

    detected_input_fields: list[str] = []
    if project_request_text:
        detected_input_fields.append("project_request_text")
    if constraints:
        detected_input_fields.append("constraints")
    if analysis_summary:
        detected_input_fields.append("analysis_summary")
    if roadmap_pr_queue:
        detected_input_fields.append("roadmap_pr_queue")
    if "active_pr_index" in selected_payload:
        detected_input_fields.append("active_pr_index")
    if active_pr:
        detected_input_fields.append("active_pr")
    if codex_result_summary:
        detected_input_fields.append("codex_result_summary")
    if "codex_validation_passed" in selected_payload:
        detected_input_fields.append("codex_validation_passed")

    missing_input_fields = [
        field_name for field_name in required_input_fields if field_name not in set(detected_input_fields)
    ]
    ready = bool(project_request_text)
    if ready:
        status = "dev_loop_input_project_request_detected"
        next_action = "prepare_project_intake"

    return {
        "project_browser_autonomous_dev_loop_input_status": status,
        "project_browser_autonomous_dev_loop_input_source": "prompt252_dev_loop_input",
        "project_browser_autonomous_dev_loop_input_payload_source": _normalize_text(
            selected_source_name,
            default="",
        ),
        "project_browser_autonomous_dev_loop_input_project_request_text": project_request_text,
        "project_browser_autonomous_dev_loop_input_constraints": constraints,
        "project_browser_autonomous_dev_loop_input_analysis_summary": analysis_summary,
        "project_browser_autonomous_dev_loop_input_roadmap_pr_queue": roadmap_pr_queue,
        "project_browser_autonomous_dev_loop_input_active_pr_index": active_pr_index,
        "project_browser_autonomous_dev_loop_input_active_pr": active_pr,
        "project_browser_autonomous_dev_loop_input_codex_result_summary": codex_result_summary,
        "project_browser_autonomous_dev_loop_input_codex_validation_passed": bool(
            codex_validation_passed
        ),
        "project_browser_autonomous_dev_loop_input_detected_input_fields": detected_input_fields,
        "project_browser_autonomous_dev_loop_input_missing_input_fields": missing_input_fields,
        "project_browser_autonomous_dev_loop_input_ready": bool(ready),
        "project_browser_autonomous_dev_loop_input_next_action": next_action,
    }

def _build_project_browser_autonomous_project_intake_state(
    *,
    dev_loop_input_state: Mapping[str, Any],
) -> dict[str, Any]:
    project_request_text = _normalize_text(
        dev_loop_input_state.get("project_browser_autonomous_dev_loop_input_project_request_text"),
        default="",
    )
    constraints = _normalize_string_list(
        dev_loop_input_state.get("project_browser_autonomous_dev_loop_input_constraints")
    )

    project_request_detected = bool(project_request_text)
    project_goal_summary = ""
    status = "project_intake_waiting_for_project_request"
    ready = False
    block_reason = "missing_project_request"
    next_action = "provide_project_request"
    if project_request_detected:
        project_goal_summary = project_request_text[:280]
        status = "project_intake_ready"
        ready = True
        block_reason = ""
        next_action = "prepare_project_analysis_request"

    return {
        "project_browser_autonomous_project_intake_status": status,
        "project_browser_autonomous_project_intake_source": "prompt252_project_intake",
        "project_browser_autonomous_project_intake_project_request_detected": bool(
            project_request_detected
        ),
        "project_browser_autonomous_project_intake_project_request_text": project_request_text,
        "project_browser_autonomous_project_intake_project_goal_summary": project_goal_summary,
        "project_browser_autonomous_project_intake_constraints": constraints,
        "project_browser_autonomous_project_intake_ready": bool(ready),
        "project_browser_autonomous_project_intake_block_reason": block_reason,
        "project_browser_autonomous_project_intake_next_action": next_action,
    }

def _build_project_browser_autonomous_project_analysis_request_state(
    *,
    project_intake_state: Mapping[str, Any],
    explicit_analysis_summary: str,
    repo_path: str,
) -> dict[str, Any]:
    project_intake_ready = bool(
        project_intake_state.get("project_browser_autonomous_project_intake_ready", False)
    )
    project_request_text = _normalize_text(
        project_intake_state.get(
            "project_browser_autonomous_project_intake_project_request_text"
        ),
        default="",
    )
    constraints = _normalize_string_list(
        project_intake_state.get("project_browser_autonomous_project_intake_constraints")
    )
    normalized_analysis_summary = _normalize_text(explicit_analysis_summary, default="")

    status = "project_analysis_request_blocked_project_intake_not_ready"
    ready = False
    request_text = ""
    result_available = False
    summary = ""
    next_action = "provide_project_request"

    if project_intake_ready:
        ready = True
        if normalized_analysis_summary:
            status = "project_analysis_request_result_available"
            result_available = True
            summary = normalized_analysis_summary
            next_action = "prepare_roadmap_pr_split"
        else:
            status = "project_analysis_request_waiting_for_chatgpt_analysis"
            request_text = "\n".join(
                [
                    "Analyze this project request and prepare planning metadata.",
                    f"repo_path: {repo_path}",
                    f"project_request: {project_request_text}",
                    f"constraints: {', '.join(constraints) if constraints else 'none'}",
                    "required_output:",
                    "- project_analysis_summary",
                    "- constraint_extraction",
                    "- roadmap_pr_split_candidate_queue",
                ]
            )
            next_action = "run_chatgpt_project_analysis"

    return {
        "project_browser_autonomous_project_analysis_request_status": status,
        "project_browser_autonomous_project_analysis_request_source": (
            "prompt252_project_analysis_request"
        ),
        "project_browser_autonomous_project_analysis_request_ready": bool(ready),
        "project_browser_autonomous_project_analysis_request_text": request_text,
        "project_browser_autonomous_project_analysis_request_result_available": bool(
            result_available
        ),
        "project_browser_autonomous_project_analysis_request_summary": summary,
        "project_browser_autonomous_project_analysis_request_next_action": next_action,
    }

def _build_project_browser_autonomous_roadmap_pr_split_queue_state(
    *,
    project_analysis_request_state: Mapping[str, Any],
    explicit_pr_queue: list[Mapping[str, Any]] | None,
    explicit_active_pr_index: int,
    explicit_active_pr: Mapping[str, Any] | None,
) -> dict[str, Any]:
    analysis_result_available = bool(
        project_analysis_request_state.get(
            "project_browser_autonomous_project_analysis_request_result_available",
            False,
        )
    )

    normalized_pr_queue: list[dict[str, Any]] = []
    if isinstance(explicit_pr_queue, list):
        for entry in explicit_pr_queue:
            if isinstance(entry, Mapping):
                normalized_pr_queue.append(dict(entry))
    explicit_active_pr_normalized = (
        dict(explicit_active_pr) if isinstance(explicit_active_pr, Mapping) else {}
    )
    normalized_active_index = _as_non_negative_int(explicit_active_pr_index, default=0)

    def _first_incomplete_pr_index(queue_payload: list[dict[str, Any]]) -> int:
        for idx, queue_entry in enumerate(queue_payload):
            completed_flag = bool(
                queue_entry.get("completed")
                or queue_entry.get("done")
                or _normalize_text(queue_entry.get("status"), default="").lower()
                in {"done", "completed", "merged", "closed"}
            )
            if not completed_flag:
                return idx
        return 0

    status = "roadmap_pr_split_queue_blocked_project_analysis_not_ready"
    ready = False
    roadmap_available = False
    active_pr_index = 0
    active_pr: dict[str, Any] = {}
    next_action = "run_chatgpt_project_analysis"

    if normalized_pr_queue:
        ready = True
        roadmap_available = True
        if 0 <= normalized_active_index < len(normalized_pr_queue):
            active_pr_index = normalized_active_index
        else:
            active_pr_index = _first_incomplete_pr_index(normalized_pr_queue)
        active_pr = (
            explicit_active_pr_normalized
            if explicit_active_pr_normalized
            else dict(normalized_pr_queue[active_pr_index])
        )
        status = "roadmap_pr_split_queue_ready"
        next_action = "generate_next_pr_prompt"
    elif analysis_result_available:
        ready = True
        status = "roadmap_pr_split_queue_waiting_for_roadmap_pr_split"
        next_action = "run_chatgpt_roadmap_pr_split"

    return {
        "project_browser_autonomous_roadmap_pr_split_queue_status": status,
        "project_browser_autonomous_roadmap_pr_split_queue_source": (
            "prompt252_roadmap_pr_split_queue"
        ),
        "project_browser_autonomous_roadmap_pr_split_queue_ready": bool(ready),
        "project_browser_autonomous_roadmap_pr_split_queue_roadmap_available": bool(
            roadmap_available
        ),
        "project_browser_autonomous_roadmap_pr_split_queue_pr_queue": normalized_pr_queue,
        "project_browser_autonomous_roadmap_pr_split_queue_total_pr_count": len(
            normalized_pr_queue
        ),
        "project_browser_autonomous_roadmap_pr_split_queue_active_pr_index": active_pr_index,
        "project_browser_autonomous_roadmap_pr_split_queue_active_pr": active_pr,
        "project_browser_autonomous_roadmap_pr_split_queue_next_action": next_action,
    }

def _build_project_browser_autonomous_dev_loop_mvp_state(
    *,
    project_intake_state: Mapping[str, Any],
    project_analysis_request_state: Mapping[str, Any],
    roadmap_pr_split_queue_state: Mapping[str, Any],
    pr_prompt_generation_state: Mapping[str, Any],
    codex_handoff_state: Mapping[str, Any],
    codex_result_review_decision_state: Mapping[str, Any],
    commit_next_pr_metadata_state: Mapping[str, Any] | None = None,
    dev_loop_completion_state: Mapping[str, Any] | None = None,
) -> dict[str, Any]:
    project_request_detected = bool(
        project_intake_state.get(
            "project_browser_autonomous_project_intake_project_request_detected",
            False,
        )
    )
    project_analysis_ready = bool(
        project_analysis_request_state.get(
            "project_browser_autonomous_project_analysis_request_result_available",
            False,
        )
    )
    roadmap_ready = bool(
        roadmap_pr_split_queue_state.get(
            "project_browser_autonomous_roadmap_pr_split_queue_roadmap_available",
            False,
        )
    )
    active_pr_index = _as_non_negative_int(
        roadmap_pr_split_queue_state.get(
            "project_browser_autonomous_roadmap_pr_split_queue_active_pr_index"
        ),
        default=0,
    )
    pr_prompt_ready = bool(
        pr_prompt_generation_state.get(
            "project_browser_autonomous_pr_prompt_generation_prompt_ready",
            False,
        )
    )
    codex_handoff_ready = bool(
        codex_handoff_state.get("project_browser_autonomous_codex_handoff_ready", False)
    )
    codex_result_detected = bool(
        codex_result_review_decision_state.get(
            "project_browser_autonomous_codex_result_review_decision_result_detected",
            False,
        )
    )
    review_decision = _normalize_text(
        codex_result_review_decision_state.get(
            "project_browser_autonomous_codex_result_review_decision_review_decision"
        ),
        default="waiting",
    )
    completion_state = (
        dict(dev_loop_completion_state)
        if isinstance(dev_loop_completion_state, Mapping)
        else {}
    )
    completion_status = _normalize_text(
        completion_state.get("project_browser_autonomous_dev_loop_completion_status"),
        default="",
    )

    status = "waiting_for_project_request"
    current_stage = "project_intake"
    next_action = "provide_project_request"
    block_reason = "missing_project_request"
    should_continue = False
    should_stop = True

    if project_request_detected:
        if review_decision == "approve":
            status = "codex_result_approved"
            current_stage = "commit_or_next_pr_decision"
            next_action = "commit_externally_or_generate_next_pr"
            block_reason = ""
            should_continue = True
            should_stop = False
        elif review_decision == "fix":
            status = "codex_result_needs_fix"
            current_stage = "fix_prompt_generation"
            next_action = "revise_pr_prompt_or_retry_codex"
            block_reason = "codex_result_validation_failed"
            should_continue = True
            should_stop = False
        elif codex_handoff_ready and not codex_result_detected:
            status = "waiting_for_codex_result"
            current_stage = "codex_result_review"
            next_action = "await_codex_result"
            block_reason = ""
            should_continue = False
            should_stop = True
        elif pr_prompt_ready:
            status = "pr_prompt_ready"
            current_stage = "codex_handoff"
            next_action = "handoff_prompt_to_codex"
            block_reason = ""
            should_continue = True
            should_stop = False
        elif roadmap_ready:
            status = "waiting_for_pr_prompt_generation"
            current_stage = "pr_prompt_generation"
            next_action = "generate_next_pr_prompt"
            block_reason = "pr_prompt_not_generated"
            should_continue = True
            should_stop = False
        elif project_analysis_ready:
            status = "waiting_for_roadmap_pr_split"
            current_stage = "roadmap_pr_split"
            next_action = "run_chatgpt_roadmap_pr_split"
            block_reason = "missing_roadmap_pr_queue"
            should_continue = True
            should_stop = False
        else:
            status = "waiting_for_project_analysis"
            current_stage = "project_analysis"
            next_action = "run_chatgpt_project_analysis"
            block_reason = "missing_project_analysis"
            should_continue = True
            should_stop = False
        if completion_status == "dev_loop_completion_project_complete":
            status = "project_complete"
            current_stage = "project_complete"
            next_action = "complete_project"
            block_reason = ""
            should_continue = False
            should_stop = True
        elif completion_status == "dev_loop_completion_next_pr_ready":
            status = "waiting_for_pr_prompt_generation"
            current_stage = "next_pr_generation"
            next_action = "generate_next_pr_prompt"
            block_reason = ""
            should_continue = True
            should_stop = False
        elif completion_status == "dev_loop_completion_fix_required":
            status = "codex_result_needs_fix"
            current_stage = "fix_prompt_generation"
            next_action = "revise_pr_prompt_or_retry_codex"
            block_reason = "codex_result_validation_failed"
            should_continue = True
            should_stop = False

    return {
        "project_browser_autonomous_dev_loop_mvp_status": status,
        "project_browser_autonomous_dev_loop_mvp_source": (
            "prompt252_autonomous_dev_loop_mvp"
        ),
        "project_browser_autonomous_dev_loop_mvp_current_stage": current_stage,
        "project_browser_autonomous_dev_loop_mvp_next_action": next_action,
        "project_browser_autonomous_dev_loop_mvp_block_reason": block_reason,
        "project_browser_autonomous_dev_loop_mvp_project_request_detected": bool(
            project_request_detected
        ),
        "project_browser_autonomous_dev_loop_mvp_project_analysis_ready": bool(
            project_analysis_ready
        ),
        "project_browser_autonomous_dev_loop_mvp_roadmap_ready": bool(roadmap_ready),
        "project_browser_autonomous_dev_loop_mvp_active_pr_index": active_pr_index,
        "project_browser_autonomous_dev_loop_mvp_pr_prompt_ready": bool(pr_prompt_ready),
        "project_browser_autonomous_dev_loop_mvp_codex_handoff_ready": bool(
            codex_handoff_ready
        ),
        "project_browser_autonomous_dev_loop_mvp_codex_result_detected": bool(
            codex_result_detected
        ),
        "project_browser_autonomous_dev_loop_mvp_review_decision": review_decision,
        "project_browser_autonomous_dev_loop_mvp_commit_allowed": False,
        "project_browser_autonomous_dev_loop_mvp_should_continue": bool(should_continue),
        "project_browser_autonomous_dev_loop_mvp_should_stop": bool(should_stop),
    }

def _build_project_browser_autonomous_dev_loop_synthetic_input_seed_state(
    *,
    dry_run: bool,
    scenario_mode_selected: str,
    has_explicit_project_request: bool,
    has_explicit_analysis_summary: bool,
    has_explicit_roadmap_pr_queue: bool,
    has_explicit_active_pr: bool,
    has_explicit_codex_result: bool,
) -> dict[str, Any]:
    explicit_input_present = bool(
        has_explicit_project_request
        or has_explicit_analysis_summary
        or has_explicit_roadmap_pr_queue
        or has_explicit_active_pr
        or has_explicit_codex_result
    )
    enabled = bool(dry_run and not explicit_input_present)
    enabled_reason = (
        "normal_dry_run_without_explicit_dev_loop_input"
        if enabled
        else "explicit_dev_loop_input_present"
    )
    status = (
        "synthetic_input_seed_ready"
        if enabled
        else "synthetic_input_seed_skipped_explicit_input_present"
    )
    next_action = (
        "apply_synthetic_input_to_dev_loop"
        if enabled
        else "use_explicit_dev_loop_input"
    )
    normalized_scenario_mode = _normalize_text(
        scenario_mode_selected,
        default="approve_single_pr_project_complete",
    )
    synthetic_pr_queue = []
    if normalized_scenario_mode == "approve_multi_pr_next_pr_available":
        synthetic_pr_queue = [
            {
                "index": 0,
                "title": "Wire MVP dev-loop input to PR prompt handoff",
                "goal": (
                    "Verify the autonomous development MVP spine can advance from project input "
                    "to generated PR prompt and Codex handoff readiness."
                ),
                "target_files": ["automation/orchestration/planned_execution_runner.py"],
                "status": "pending",
            },
            {
                "index": 1,
                "title": "Advance MVP spine to next PR generation metadata",
                "goal": (
                    "Validate next_pr_available continuation metadata after an approved result."
                ),
                "target_files": ["automation/orchestration/planned_execution_runner.py"],
                "status": "pending",
            },
        ]
    else:
        synthetic_pr_queue = [
            {
                "index": 0,
                "title": "Wire MVP dev-loop input to PR prompt handoff",
                "goal": (
                    "Verify the autonomous development MVP spine can advance from project input "
                    "to generated PR prompt and Codex handoff readiness."
                ),
                "target_files": ["automation/orchestration/planned_execution_runner.py"],
                "status": "pending",
            }
        ]
    synthetic_active_pr = dict(synthetic_pr_queue[0])

    return {
        "project_browser_autonomous_dev_loop_synthetic_input_seed_status": status,
        "project_browser_autonomous_dev_loop_synthetic_input_seed_source": (
            "prompt253_dev_loop_synthetic_input_seed"
        ),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_enabled": bool(enabled),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_enabled_reason": (
            enabled_reason
        ),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_project_request_text": (
            "Build a minimal autonomous development MVP control loop for this repository."
            if enabled
            else ""
        ),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_analysis_summary": (
            "MVP needs project intake, roadmap/PR split metadata, PR prompt generation, Codex handoff, result review, and commit/fix decision metadata."
            if enabled
            else ""
        ),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_roadmap_pr_queue": (
            synthetic_pr_queue if enabled else []
        ),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_active_pr_index": 0,
        "project_browser_autonomous_dev_loop_synthetic_input_seed_active_pr": (
            synthetic_active_pr if enabled else {}
        ),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_ready": bool(enabled),
        "project_browser_autonomous_dev_loop_synthetic_input_seed_next_action": next_action,
    }

def _build_project_browser_autonomous_commit_next_pr_metadata_state(
    *,
    review_decision: str,
    roadmap_pr_queue: list[Mapping[str, Any]] | None,
    active_pr_index: int,
) -> dict[str, Any]:
    normalized_review_decision = _normalize_text(review_decision, default="waiting")
    normalized_queue: list[dict[str, Any]] = []
    if isinstance(roadmap_pr_queue, list):
        for entry in roadmap_pr_queue:
            if isinstance(entry, Mapping):
                normalized_queue.append(dict(entry))
    normalized_active_pr_index = _as_non_negative_int(active_pr_index, default=0)

    next_pr_available = bool(
        normalized_queue and (normalized_active_pr_index + 1) < len(normalized_queue)
    )
    next_pr_index = (
        normalized_active_pr_index + 1 if next_pr_available else normalized_active_pr_index
    )

    status = "commit_next_pr_metadata_waiting_for_review_decision"
    commit_candidate = False
    commit_message_suggestion = ""
    tag_suggestion = ""
    external_commit_command_suggestion = ""
    external_tag_command_suggestion = ""
    next_action = "await_codex_result"

    if normalized_review_decision == "approve":
        status = "commit_next_pr_metadata_ready"
        commit_candidate = True
        commit_message_suggestion = "Record autonomous MVP PR result"
        tag_suggestion = "prompt255-commit-next-pr-metadata"
        external_commit_command_suggestion = (
            "git commit -m \"Record autonomous MVP PR result\""
        )
        external_tag_command_suggestion = "git tag prompt255-commit-next-pr-metadata"
        next_action = (
            "generate_next_pr_prompt"
            if next_pr_available
            else "complete_project_metadata"
        )
    elif normalized_review_decision == "fix":
        status = "commit_next_pr_metadata_blocked_needs_fix"
        next_pr_available = False
        next_pr_index = normalized_active_pr_index
        next_action = "revise_pr_prompt_or_retry_codex"

    return {
        "project_browser_autonomous_commit_next_pr_metadata_status": status,
        "project_browser_autonomous_commit_next_pr_metadata_source": (
            "prompt255_commit_next_pr_metadata"
        ),
        "project_browser_autonomous_commit_next_pr_metadata_review_decision": (
            normalized_review_decision
        ),
        "project_browser_autonomous_commit_next_pr_metadata_commit_candidate": bool(
            commit_candidate
        ),
        "project_browser_autonomous_commit_next_pr_metadata_commit_allowed": False,
        "project_browser_autonomous_commit_next_pr_metadata_merge_allowed": False,
        "project_browser_autonomous_commit_next_pr_metadata_push_allowed": False,
        "project_browser_autonomous_commit_next_pr_metadata_commit_message_suggestion": (
            commit_message_suggestion
        ),
        "project_browser_autonomous_commit_next_pr_metadata_tag_suggestion": (
            tag_suggestion
        ),
        "project_browser_autonomous_commit_next_pr_metadata_external_commit_command_suggestion": (
            external_commit_command_suggestion
        ),
        "project_browser_autonomous_commit_next_pr_metadata_external_tag_command_suggestion": (
            external_tag_command_suggestion
        ),
        "project_browser_autonomous_commit_next_pr_metadata_next_pr_available": bool(
            next_pr_available
        ),
        "project_browser_autonomous_commit_next_pr_metadata_next_pr_index": next_pr_index,
        "project_browser_autonomous_commit_next_pr_metadata_next_action": next_action,
    }

def _build_project_browser_autonomous_dev_loop_completion_state(
    *,
    current_stage: str,
    review_decision: str,
    next_pr_available: bool,
) -> dict[str, Any]:
    normalized_current_stage = _normalize_text(current_stage, default="codex_result_review")
    normalized_review_decision = _normalize_text(review_decision, default="waiting")
    normalized_next_pr_available = bool(next_pr_available)

    status = "dev_loop_completion_waiting_for_review_decision"
    completion_stage = normalized_current_stage
    project_complete = False
    should_generate_next_pr = False
    should_retry_fix = False
    should_stop = False
    next_action = "await_codex_result"

    if normalized_review_decision == "approve" and normalized_next_pr_available:
        status = "dev_loop_completion_next_pr_ready"
        completion_stage = "next_pr_generation"
        should_generate_next_pr = True
        should_stop = False
        next_action = "generate_next_pr_prompt"
    elif normalized_review_decision == "approve" and not normalized_next_pr_available:
        status = "dev_loop_completion_project_complete"
        completion_stage = "project_complete"
        project_complete = True
        should_stop = True
        next_action = "complete_project"
    elif normalized_review_decision == "fix":
        status = "dev_loop_completion_fix_required"
        completion_stage = "fix_prompt_generation"
        should_retry_fix = True
        should_stop = False
        next_action = "revise_pr_prompt_or_retry_codex"

    return {
        "project_browser_autonomous_dev_loop_completion_status": status,
        "project_browser_autonomous_dev_loop_completion_source": (
            "prompt255_dev_loop_completion"
        ),
        "project_browser_autonomous_dev_loop_completion_current_stage": completion_stage,
        "project_browser_autonomous_dev_loop_completion_review_decision": (
            normalized_review_decision
        ),
        "project_browser_autonomous_dev_loop_completion_next_pr_available": bool(
            normalized_next_pr_available
        ),
        "project_browser_autonomous_dev_loop_completion_project_complete": bool(
            project_complete
        ),
        "project_browser_autonomous_dev_loop_completion_should_generate_next_pr": bool(
            should_generate_next_pr
        ),
        "project_browser_autonomous_dev_loop_completion_should_retry_fix": bool(
            should_retry_fix
        ),
        "project_browser_autonomous_dev_loop_completion_should_stop": bool(should_stop),
        "project_browser_autonomous_dev_loop_completion_next_action": next_action,
    }

def _build_project_browser_autonomous_mvp_scenario_mode_state(
    *,
    dry_run: bool,
    explicit_mode: str,
    explicit_input_present: bool,
) -> dict[str, Any]:
    allowed_modes = [
        "approve_single_pr_project_complete",
        "failed_result_fix_route",
        "approve_multi_pr_next_pr_available",
    ]
    explicit_mode_normalized = _normalize_text(explicit_mode, default="")
    selected = "approve_single_pr_project_complete"
    selection_source = "default_dry_run"
    status = "mvp_scenario_mode_ready"
    ready = bool(dry_run)
    next_action = "apply_mvp_scenario_mode" if ready else "use_explicit_dev_loop_input"

    if explicit_mode_normalized:
        if explicit_mode_normalized in set(allowed_modes):
            selected = explicit_mode_normalized
            selection_source = "explicit_metadata"
        elif dry_run:
            selected = "approve_single_pr_project_complete"
            selection_source = "default_dry_run_invalid_explicit_mode"
            status = "mvp_scenario_mode_defaulted_invalid_mode"
        else:
            selected = "approve_single_pr_project_complete"
            selection_source = "invalid_explicit_mode_without_dry_run"
            status = "mvp_scenario_mode_not_ready"
            ready = False
            next_action = "use_explicit_dev_loop_input"
    elif not dry_run:
        selected = "approve_single_pr_project_complete"
        selection_source = "not_selected_non_dry_run"
        status = "mvp_scenario_mode_not_ready"
        ready = False
        next_action = "use_explicit_dev_loop_input"

    return {
        "project_browser_autonomous_mvp_scenario_mode_status": status,
        "project_browser_autonomous_mvp_scenario_mode_source": (
            "prompt256_mvp_scenario_mode"
        ),
        "project_browser_autonomous_mvp_scenario_mode_selected": selected,
        "project_browser_autonomous_mvp_scenario_mode_selection_source": (
            selection_source
        ),
        "project_browser_autonomous_mvp_scenario_mode_allowed_modes": allowed_modes,
        "project_browser_autonomous_mvp_scenario_mode_explicit_input_present": bool(
            explicit_input_present
        ),
        "project_browser_autonomous_mvp_scenario_mode_ready": bool(ready),
        "project_browser_autonomous_mvp_scenario_mode_next_action": next_action,
    }

def _build_project_browser_autonomous_mvp_scenario_result_matrix_state(
    *,
    selected_mode: str,
    observed_final_status: str,
    observed_next_action: str,
) -> dict[str, Any]:
    normalized_mode = _normalize_text(
        selected_mode,
        default="approve_single_pr_project_complete",
    )
    normalized_observed_status = _normalize_text(observed_final_status, default="")
    normalized_observed_action = _normalize_text(observed_next_action, default="")

    expected_status = "project_complete"
    expected_action = "complete_project"
    if normalized_mode == "failed_result_fix_route":
        expected_status = "codex_result_needs_fix"
        expected_action = "revise_pr_prompt_or_retry_codex"
    elif normalized_mode == "approve_multi_pr_next_pr_available":
        expected_status = "waiting_for_pr_prompt_generation"
        expected_action = "generate_next_pr_prompt"

    passed = bool(
        normalized_observed_status == expected_status
        and normalized_observed_action == expected_action
    )
    status = (
        "mvp_scenario_result_matrix_passed"
        if passed
        else "mvp_scenario_result_matrix_failed"
    )
    next_action = "scenario_matrix_validated" if passed else "inspect_scenario_mismatch"

    return {
        "project_browser_autonomous_mvp_scenario_result_matrix_status": status,
        "project_browser_autonomous_mvp_scenario_result_matrix_source": (
            "prompt256_mvp_scenario_result_matrix"
        ),
        "project_browser_autonomous_mvp_scenario_result_matrix_selected_mode": (
            normalized_mode
        ),
        "project_browser_autonomous_mvp_scenario_result_matrix_expected_final_status": (
            expected_status
        ),
        "project_browser_autonomous_mvp_scenario_result_matrix_observed_final_status": (
            normalized_observed_status
        ),
        "project_browser_autonomous_mvp_scenario_result_matrix_expected_next_action": (
            expected_action
        ),
        "project_browser_autonomous_mvp_scenario_result_matrix_observed_next_action": (
            normalized_observed_action
        ),
        "project_browser_autonomous_mvp_scenario_result_matrix_passed": bool(passed),
        "project_browser_autonomous_mvp_scenario_result_matrix_next_action": next_action,
    }

